#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

HOST="${SUKKAL_HOST:-amaterasu}"
PGVER=18
REMOTE_SCRIPT=/tmp/sukkal-provision-root.sh

banner "Provision PostgreSQL $PGVER for Sukkal on $HOST"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the things that would stop this half way through."
echo

ok=1
if ssh -o ConnectTimeout=6 -o BatchMode=yes "$HOST" true 2>/dev/null; then
  say "  ${GREEN}ok${RESET}  ssh to $HOST works with a key"
else
  say "  ${RED}no${RESET}  ssh to $HOST failed. Fix that first."; ok=0
fi

if ssh -o BatchMode=yes "$HOST" 'sudo -n apt-get --version >/dev/null 2>&1'; then
  say "  ${GREEN}ok${RESET}  apt-get already runs without a password"
else
  say "  ${YELLOW}--${RESET}  apt-get will prompt for your password"
fi

# `|| true` on every assignment below: the library sets `set -e`, and a bare
# assignment takes the exit status of its command substitution, so a failed ssh
# would kill the wizard mid-sentence instead of being reported here.
SRC_IP=$(ssh -o BatchMode=yes "$HOST" 'echo $SSH_CLIENT' 2>/dev/null | awk '{print $1}' || true)
if [[ ! "$SRC_IP" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  say "  ${RED}no${RESET}  could not read the address $HOST sees this Mac as."
  say "      pg_hba would get a malformed network, so stop here."
  ok=0
fi
SRC_NET=$(echo "$SRC_IP" | awk -F. '{print $1"."$2"."$3".0/24"}' || true)
say "  ${GREEN}ok${RESET}  $HOST sees this Mac as $SRC_IP, so pg_hba will allow $SRC_NET"
echo
say "${YELLOW}That subnet comes from whichever interface carried this ssh.${RESET}"
say "Wired and Wi-Fi share one flat /24 here, so either interface reaches Postgres."
say "Moving the Mac to another subnet, a guest SSID or a VLAN needs a second"
say "hostssl line for it."
echo

RAM_MB=$(ssh -o BatchMode=yes "$HOST" "awk '/MemTotal/{print int(\$2/1024)}' /proc/meminfo" || true)
say "  $HOST reports ${RAM_MB} MB of RAM. The tuning below is sized for that."
say "  nabium's runbook targets a 32 GB host, so its numbers are scaled down"
say "  rather than copied. shared_buffers 512MB, work_mem 16MB,"
say "  effective_cache_size 2GB, max_connections 25."
echo
[[ $ok -eq 1 ]] || { say "${RED}Stopping.${RESET}"; exit 1; }

say "This wizard will, in one sudo prompt on $HOST:"
step "install postgresql-$PGVER and postgresql-$PGVER-pgvector from PGDG"
step "create the sukkal role, the sukkal database and the sukkal_dev database"
step "generate a TLS certificate and require encrypted connections"
step "bind to the LAN address only, never 0.0.0.0"
step "apply the tuning above"
echo
say "It creates no read-only role. Nothing in this slice consumes one."
echo
confirm "Provision $HOST now?" || { say "Nothing changed."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Provision the server"
say "Generating a password for the sukkal role on this Mac."
say "It is written to .env here and set on the server. It is never printed."
# head closes the pipe once it has 32 bytes, so tr takes SIGPIPE and exits 141.
# With pipefail that kills the wizard here on every single run. Guard it, then
# check the result: a silently empty password would be set on the role.
SUKKAL_PASSWORD=$(LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c 32 || true)
if [[ ${#SUKKAL_PASSWORD} -ne 32 ]]; then
  say "  ${RED}no${RESET}  could not generate a password. Nothing was changed."
  exit 1
fi

say "Copying the root script to $HOST."
sed -e "s|@@PGVER@@|$PGVER|g" -e "s|@@SRCNET@@|$SRC_NET|g" \
    -e "s|@@PASSWORD@@|$SUKKAL_PASSWORD|g" \
    "$(dirname "$0")/provision-amaterasu-root.sh" \
  | ssh -o BatchMode=yes "$HOST" "cat > $REMOTE_SCRIPT && chmod 600 $REMOTE_SCRIPT"

echo
say "${BOLD}Type your sudo password when $HOST asks. It goes to sudo, nowhere else.${RESET}"
echo
ssh -t "$HOST" "sudo bash $REMOTE_SCRIPT; rc=\$?; rm -f $REMOTE_SCRIPT; exit \$rc"
say "${GREEN}Server provisioned.${RESET}"
pause "Continue to verification?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Verify from this Mac"
say "Every check below runs from here, over the LAN, exactly as the migration will."
echo
HOST_IP=$(ssh -o BatchMode=yes "$HOST" "hostname -I | awk '{print \$1}'" || true)
if [[ ! "$HOST_IP" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
  say "  ${RED}no${RESET}  could not read $HOST's own address. Cannot verify."
  exit 1
fi
export PGPASSWORD="$SUKKAL_PASSWORD"
PSQL_BASE="psql -h $HOST_IP -U sukkal -d sukkal -tAX"

run_check() {  # run_check "label" "sql" "expected"
  local got; got=$($PSQL_BASE -c "$2" 2>&1 | tr -d '[:space:]')
  if [[ "$got" == "$3" ]]; then say "  ${GREEN}ok${RESET}  $1"; else
    say "  ${RED}no${RESET}  $1 (got '$got', wanted '$3')"; FAILED=1; fi
}

FAILED=0
say "  ${DIM}connecting with sslmode=require${RESET}"
export PGSSLMODE=require
run_check "pgvector is installed"      "SELECT count(*) FROM pg_extension WHERE extname='vector'" "1"
run_check "the connection is encrypted" "SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()" "t"
run_check "sukkal is not a superuser"      "SELECT rolsuper FROM pg_roles WHERE rolname='sukkal'" "f"
run_check "no read-only role exists"    "SELECT count(*) FROM pg_roles WHERE rolname='sukkal_ro'" "0"
run_check "sukkal_dev exists"              "SELECT count(*) FROM pg_database WHERE datname='sukkal_dev'" "1"
run_check "the server is not on 0.0.0.0" "SELECT setting <> '*' FROM pg_settings WHERE name='listen_addresses'" "t"

say "  ${DIM}checking that an unencrypted client is refused${RESET}"
if PGSSLMODE=disable psql -h "$HOST_IP" -U sukkal -d sukkal -tAXc 'SELECT 1' >/dev/null 2>&1; then
  say "  ${RED}no${RESET}  an unencrypted connection was accepted"; FAILED=1
else
  say "  ${GREEN}ok${RESET}  an unencrypted connection is refused"
fi
echo
[[ $FAILED -eq 0 ]] || { say "${RED}Verification failed. Fix before continuing.${RESET}"; exit 1; }
say "${GREEN}All checks passed.${RESET}"
pause "Write the connection details?"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Write the connection details"
say "These go into .env, which is git-ignored. Nothing is committed."
write_env DATABASE_URL      "postgresql://sukkal:${SUKKAL_PASSWORD}@${HOST_IP}:5432/sukkal?sslmode=require"
write_env DATABASE_URL_TEST "postgresql://sukkal:${SUKKAL_PASSWORD}@${HOST_IP}:5432/sukkal_dev?sslmode=require"
say "Tests point at sukkal_dev, so a test run never writes into the migration's data."
pause "Continue to the reboot check?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Survive a restart"
say "A service that works until the next reboot is not provisioned."
echo
ssh -t "$HOST" "sudo systemctl restart postgresql@${PGVER}-main"
sleep 3
if $PSQL_BASE -c 'SELECT 1' >/dev/null 2>&1; then
  say "  ${GREEN}ok${RESET}  the service came back after a restart"
else
  say "  ${RED}no${RESET}  the service did not come back"; exit 1
fi
say "  ${DIM}enabled at boot:${RESET} $(ssh -o BatchMode=yes "$HOST" "systemctl is-enabled postgresql")"
echo
say "A full reboot is the real test and it interrupts NFS and any transcode."
say "Run it yourself when the box is quiet: ${BOLD}ssh $HOST sudo reboot${RESET}"
pause "Continue to the backup drill?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Back up and restore once"
say "A runbook nobody has followed is a runbook that does not work."
echo
# The SQL below carries no single quote and no dollar sign, on purpose. It
# passes through a local double-quoted string, an ssh argument and a remote
# single-quoted `bash -c`, and a single quote would close that region early. The
# 2026-08-26 run wrote 'public' as \x27public\x27 and lost the escape in that
# chain, so psql answered with a syntax error and the count printed empty.
# current_schema() is public for the postgres user, so it says the same thing.
if confirm "Run a dump and restore into a scratch database now?"; then
  ssh -t "$HOST" "sudo -u postgres bash -c '
    set -e
    pg_dump sukkal > /tmp/sukkal-drill.sql
    dropdb --if-exists sukkal_drill
    createdb sukkal_drill
    psql -q -d sukkal_drill -f /tmp/sukkal-drill.sql
    echo \"restored objects: \$(psql -tAX -d sukkal_drill -c \"SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = current_schema()\")\"
    dropdb sukkal_drill
    rm -f /tmp/sukkal-drill.sql'"
  say "  ${GREEN}ok${RESET}  dump and restore completed, scratch database removed"
else
  SKIPPED+=("the backup drill: KPA-22 stays open until it runs")
fi

finish
